<?php require_once __DIR__.'/../includes/auth.php';require_role('admin');$rows=db()->query('SELECT r.*,u.name customer,c.name category FROM service_requests r JOIN users u ON u.id=r.customer_id JOIN categories c ON c.id=r.category_id ORDER BY r.id DESC LIMIT 200')->fetchAll();$pageTitle='Requests — Admin';require __DIR__.'/../includes/header.php';?><div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>Service requests</h1><div class="table-responsive"><table class="table"><tr><th>#</th><th>Customer</th><th>Category</th><th>Title</th><th>Status</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['customer'])?></td><td><?=e($r['category'])?></td><td><?=e($r['title'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>